import React from "react";

function Header() {
  return (
    <header className="bg-white shadow-md">
      <div className="container mx-auto flex items-center justify-between px-6 py-4">
        <div className="text-2xl font-bold text-blue-700">Luminos</div>
        <nav className="space-x-6 hidden md:block">
          <a href="#features" className="text-gray-700 hover:text-blue-700">Features</a>
          <a href="#demo" className="text-gray-700 hover:text-blue-700">Book a Demo</a>
          <a href="#contact" className="text-gray-700 hover:text-blue-700">Contact</a>
        </nav>
      </div>
    </header>
  );
}

export default Header;
